2	// BNS (Bigwash Native Shell) - 데이터 모델
3	// ============================================================================
4	// HTTP 요청/응답, API 데이터 구조 정의
5	
6	module bns_models {
7	    // === HTTP 요청 ===
8	    struct HttpRequest {
9	        method:      string;     // "GET", "POST", "SSE"
10	        path:        string;     // "/api/status", "/api/gogs", ...
11	        query:       string;     // "?repo=zero-copy-db"
12	        body:        string;     // POST 바디
13	        headers:     [string];   // 헤더 배열
14	    }
15	
16	    // === HTTP 응답 ===
17	    struct HttpResponse {
18	        status_code: i32;        // 200, 404, 500
19	        content_type: string;    // "application/json", "text/event-stream"
20	        body:        string;     // 응답 바디
21	        is_sse:      bool;       // true면 Server-Sent Events
22	    }
23	
24	    // === Project 상태 ===
25	    struct ProjectStatus {
26	        name:        string;     // "Zero-Copy-DB"
27	        phase:       i32;        // 11
28	        lines:       i32;        // 22439
29	        files:       i32;        // 56
30	        tests:       i32;        // 182
31	        status:      string;     // "✅ COMPLETE"
32	    }
33	
34	    // === Gogs 커밋 정보 ===
35	    struct GogsCommit {
36	        hash:        string;     // "2bc0873"
37	        message:     string;     // "perf: 성능 최적화"
38	        repo:        string;     // "zero-copy-db"
39	        date:        string;     // "2026-03-29"
40	        files_changed: i32;      // 2
41	        insertions:  i32;        // 89
42	        deletions:   i32;        // 45
43	    }
44	
45	    // === SSE 이벤트 ===
46	    struct SseEvent {
47	        event_type:  string;     // "commit", "test", "build"
48	        data:        string;     // JSON 문자열
49	        timestamp:   i64;        // Unix timestamp
50	    }
51	
52	    // === 시스템 실행 결과 (Git Log, 외부 커맨드) ===
53	    struct SysExecResult {
54	        output:      string;     // 커맨드 출력
55	        success:     bool;       // 성공 여부
56	        exit_code:   i32;        // 종료 코드 (0=성공)
57	    }
58	
59	    // === API 응답 - Status ===
60	    struct ApiStatusResponse {
61	        last_update: string;
62	        projects:    [ProjectStatus];
63	        total_lines: i32;
64	        total_tests: i32;
65	    }
66	
67	    // === API 응답 - Gogs ===
68	    struct ApiGogsResponse {
69	        recent_commits: [GogsCommit];
70	        repo_count:     i32;
71	        total_commits:  i32;
72	    }
73	
74	    // === 에러 응답 ===
75	    struct ApiError {
76	        error:       string;
77	        message:     string;
78	        code:        i32;
79	    }
80	
81	    // === 상수 ===
82	    const HTTP_OK:              i32 = 200;
83	    const HTTP_BAD_REQUEST:     i32 = 400;
84	    const HTTP_NOT_FOUND:       i32 = 404;
85	    const HTTP_INTERNAL_ERROR:  i32 = 500;
86	
87	    const CONTENT_JSON:         string = "application/json; charset=utf-8";
88	    const CONTENT_SSE:          string = "text/event-stream";
89	    const CONTENT_TEXT:         string = "text/plain";
90	
91	    // === 헬퍼 함수 ===
92	    func http_response_ok(body: string, content_type: string) -> HttpResponse {
93	        let resp: HttpResponse;
94	        resp.status_code = HTTP_OK;
95	        resp.body = body;
96	        resp.content_type = content_type;
97	        resp.is_sse = false;
98	        return resp;
99	    }
100	
101	    func http_response_error(code: i32, message: string) -> HttpResponse {
102	        let resp: HttpResponse;
103	        resp.status_code = code;
104	        resp.body = "{\"error\": \"" + message + "\"}";
105	        resp.content_type = CONTENT_JSON;
106	        resp.is_sse = false;
107	        return resp;
108	    }
109	
110	    func http_response_sse(data: string) -> HttpResponse {
111	        let resp: HttpResponse;
112	        resp.status_code = HTTP_OK;
113	        resp.body = "data: " + data + "\n\n";
114	        resp.content_type = CONTENT_SSE;
115	        resp.is_sse = true;
116	        return resp;
117	    }
118	}
