4	// /api/status, /api/gogs, /api/feed, /api/db
5	
6	module bns_handlers {
7	    use bns_models;
8	    use bns_http;
9	    use bns_broadcast;
10	    use bns_dynamic;
11	
12	    // === 라우터 ===
13	    func handle_request(req: bns_http.HttpRequest) -> bns_models.HttpResponse {
14	        // 경로별 라우팅
15	        if req.path == "/api/status" {
16	            return handle_status();
17	        } else if req.path == "/api/gogs" {
18	            return handle_gogs();
19	        } else if req.path == "/api/feed" {
20	            return handle_feed();
21	        } else if req.path == "/api/db" {
22	            return handle_db();
23	        } else if req.path == "/" {
24	            return handle_root();
25	        } else {
26	            return bns_models.http_response_error(404, "Endpoint not found");
27	        }
28	    }
29	
30	    // === /api/status - 프로젝트 상태 (동적 데이터) ===
31	    func handle_status() -> bns_models.HttpResponse {
32	        // MEMORY.md에서 동적으로 데이터 로드
33	        let json = bns_dynamic.get_status_json();
34	        return bns_models.http_response_ok(json, bns_models.CONTENT_JSON);
35	    }
36	
37	    // === /api/gogs - 최근 커밋 (동적 데이터) ===
38	    func handle_gogs() -> bns_models.HttpResponse {
39	        // Git log에서 동적으로 커밋 데이터 로드
40	        let json = bns_dynamic.get_gogs_json();
41	        return bns_models.http_response_ok(json, bns_models.CONTENT_JSON);
42	    }
43	
44	    // === /api/feed - Server-Sent Events (실시간 스트림) ===
45	    func handle_feed() -> bns_models.HttpResponse {
46	        // 브로드캐스트에 구독자 등록
47	        let (sub_ch, sub_id) = bns_broadcast.broadcast_subscribe();
48	
49	        if sub_id < 0 {
50	            // 구독자 수 초과
51	            return bns_models.http_response_error(503, "Too many subscribers");
52	        }
53	
54	        // 채널에서 이벤트 수신 시도 (100 tick 폴링)
55	        let i = 0;
56	        for i = 0; i < 100; i = i + 1 {
57	            let (idx, ok) = sub_ch.chan_recv();
58	
59	            if ok {
60	                let event_json = bns_broadcast.broadcast_get_event(idx);
61	                bns_broadcast.broadcast_unsubscribe(sub_id);
62	                return bns_models.http_response_sse(event_json);
63	            }
64	        }
65	
66	        // 타임아웃: 최신 이벤트 또는 더미 데이터 반환
67	        bns_broadcast.broadcast_unsubscribe(sub_id);
68	
69	        let latest = bns_broadcast.broadcast_get_latest();
70	        if len(latest) == 2 {  // "{}" 빈 이벤트
71	            // 아직 이벤트 없음 - 더미 반환
72	            latest = "{\"status\": \"waiting\", \"message\": \"No events yet\"}";
73	        }
74	
75	        return bns_models.http_response_sse(latest);
76	    }
77	
78	    // === /api/db - Zero-Copy-DB 상태 ===
79	    func handle_db() -> bns_models.HttpResponse {
80	        let json = "{";
81	        json = json + "\"name\": \"Zero-Copy-DB\",";
82	        json = json + "\"phase\": 11,";
83	        json = json + "\"modules\": 11,";
84	        json = json + "\"total_lines\": 22439,";
85	        json = json + "\"memory_usage_mb\": 8.5,";
86	        json = json + "\"active_transactions\": 3,";
87	        json = json + "\"cached_queries\": 12,";
88	        json = json + "\"performance\": {";
89	        json = json + "\"query_latency_ms\": 2.5,";
90	        json = json + "\"insert_throughput_per_sec\": 5000,";
91	        json = json + "\"index_hit_rate\": 0.94";
92	        json = json + "}";
93	        json = json + "}";
94	
95	        return bns_models.http_response_ok(json, bns_models.CONTENT_JSON);
96	    }
97	
98	    // === / - 루트 (홈페이지) ===
99	    func handle_root() -> bns_models.HttpResponse {
100	        let html = "<html><body>";
101	        html = html + "<h1>🚀 Bigwash Native Shell (BNS)</h1>";
102	        html = html + "<p>기록이 증명이다</p>";
103	        html = html + "<ul>";
104	        html = html + "<li><a href='/api/status'>/api/status</a> - 프로젝트 상태</li>";
105	        html = html + "<li><a href='/api/gogs'>/api/gogs</a> - Gogs 커밋</li>";
106	        html = html + "<li><a href='/api/feed'>/api/feed</a> - 실시간 피드 (SSE)</li>";
107	        html = html + "<li><a href='/api/db'>/api/db</a> - DB 상태</li>";
108	        html = html + "</ul>";
109	        html = html + "</body></html>";
110	
111	        return bns_models.http_response_ok(html, "text/html");
112	    }
113	
114	    // === 헬퍼: 정수를 문자열로 ===
115	    @inline
116	    func to_string(n: i32) -> string {
117	        if n == 0 {
118	            return "0";
119	        }
120	
121	        let negative = false;
122	        if n < 0 {
123	            negative = true;
124	            n = 0 - n;
125	        }
126	
127	        let result = "";
128	        let temp = n;
129	
130	        for temp > 0 {
131	            let digit = temp % 10;
132	            let ch = char_from_code(48 + digit);  // '0' = 48
133	            result = ch + result;
134	            temp = temp / 10;
135	        }
136	
137	        if negative {
138	            result = "-" + result;
139	        }
140	
141	        return result;
142	    }
143	}
